"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6094],{50206:e=>{e.exports=JSON.parse('{"functions":[{"name":"ClampRewind","desc":"Pure. Clamp a client-claimed render time into a safe rewind time.\\nNon-finite / non-positive input means \\"no rewind\\" (returns `now`).","params":[{"name":"now","desc":"","lua_type":"number"},{"name":"renderTime","desc":"","lua_type":"number"},{"name":"ping","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":42,"path":"src/ServerStorage/SharedModules/LagCompensation.luau"}}],"properties":[],"types":[],"name":"LagCompensation","desc":"Rewinds Chrono-tracked NPCs to the time the shooter saw them. The client\\nsends its Chrono ENEMY render time (server os.clock domain); the server\\nclamps it, reads each NPC\'s snapshot at that time, and shifts the query\\ninto the NPC\'s current pose with `delta = current * past:Inverse()` \u2014 so\\nthe query hits the real current geometry as if the NPC stood where the\\nshooter saw it. Rigid: the animated limb pose is the current one.\\n\\nPlayers are never rewound (Factions allows no PvP). World geometry and\\ndead (paused) NPCs are tested unrewound, as before.","realm":["Server"],"source":{"line":16,"path":"src/ServerStorage/SharedModules/LagCompensation.luau"}}')}}]);